inline const ItemTypeEntry* Get(const char* name) noexcept
{
    if (!name) return nullptr;
    for (std::size_t i = 0; i < kCount; ++i)
        if (std::strcmp(kData[i].name, name) == 0) return &kData[i];
    return nullptr;
}

inline const char* GetConcreteType(const char* name) noexcept
{
    const ItemTypeEntry* item = Get(name);
    return item ? item->concrete_type : nullptr;
}

inline const char* const* GetTypes(const char* name, std::size_t& count) noexcept
{
    const ItemTypeEntry* item = Get(name);
    if (!item)
    {
        count = 0;
        return nullptr;
    }
    count = item->type_count;
    return &kTypeNames[item->first_type];
}

inline bool HasType(const char* name, const char* type) noexcept
{
    if (!type) return false;
    const ItemTypeEntry* item = Get(name);
    if (!item) return false;
    for (std::size_t i = 0; i < item->type_count; ++i)
        if (std::strcmp(kTypeNames[item->first_type + i], type) == 0) return true;
    return false;
}
